const cds = require('../../../cds')
const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')
const { srv4, aicore } = require('../../registries/mta')
const KymaTemplate = require('../kyma')

module.exports = class AiTemplate extends require('../../plugin') {

    static help() {
        return 'SAP BTP AI Core'
    }

    options() {
        return {
            'plan': {
                type: 'string',
                help: 'Specify the service plan.',
            }
        }
    }

    static hasInProduction(env) {
        const { dependencies, isJava } = readProject()
        return dependencies?.['@cap-js/ai'] || isJava && env.requires?.AICore
    }

    async run() {
        const project = readProject()
        const { configFile } = project
        await merge(__dirname, 'files/package.json.hbs').into(configFile, { project })
    }

    async combine(facet) {
        const project = readProject(facet)
        const { addMta, addKyma, addMultitenancy, srv } = project
        const { plan } = cds.cli.options

        if (addMta) {
            if (plan) project.servicePlan = plan
            const srvModule = srv4(srv.path)
            await merge(__dirname, 'files/mta.yaml.hbs').into('mta.yaml', {
                with: project,
                additions: [srvModule, aicore],
                relationships: [{
                    insert: [aicore, 'name'],
                    into: [srvModule, 'requires', 'name']
                }]
            })
        }

        if (addKyma) {
            await merge(__dirname, 'files/values.yaml').into('chart/values.yaml')
            await KymaTemplate.mergeDependency('service-instance', 'aicore')
        }

        if (addMultitenancy) {
            await merge(__dirname, 'files/package.json.hbs').into('mtx/sidecar/package.json', { project })
        }
    }
}
